#include <cmath>
#include <cstdio>
#include <vector>
#include <string>
#include <algorithm>
#include "../fluidSim-cuda/kernels.cu"
const int W=256,H=32,N=W*H;const double OMEGA=double(1.2f);
const int DX[9]={0,1,0,-1,0,1,-1,-1,1},DY[9]={0,0,1,0,-1,1,1,-1,-1};const double WEIGHT[9]={4./9,1./9,1./9,1./9,1./9,1./36,1./36,1./36,1./36};
static double eq(double r,double w,int dx,int dy,double ux,double uy){double u2=ux*ux+uy*uy,eu=dx*ux+dy*uy;return r*w*(1+3*eu+4.5*eu*eu-1.5*u2);}
static void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
struct Case{std::vector<double>a,b,c,want;std::vector<unsigned char>types;double *da,*oa;double4 *db,*ob,*dc,*oc;bool*dt;};
static std::vector<double>encode(const std::vector<double>&f){std::vector<double>out;for(int p=0;p<N;++p)out.push_back(f[p*9]);for(int p=0;p<N;++p)for(int k=1;k<5;++k)out.push_back(f[p*9+k]);for(int p=0;p<N;++p)for(int k=5;k<9;++k)out.push_back(f[p*9+k]);return out;}
static std::vector<double>oracle(Case&c){std::vector<double>f(N*9),out,collision(N*9);int opp[9]={0,3,4,1,2,7,8,5,6};for(int p=0;p<N;++p){f[p*9]=c.a[p];for(int k=0;k<4;++k){f[p*9+k+1]=c.b[p*4+k];f[p*9+k+5]=c.c[p*4+k];}}out=f;for(int t=0;t<8;++t){for(int p=0;p<N;++p){if(c.types[p])for(int k=0;k<9;++k)collision[p*9+k]=f[p*9+opp[k]];else{double r=0,ux=0,uy=0;for(int k=0;k<9;++k){double v=f[p*9+k];r+=v;ux+=v*DX[k];uy+=v*DY[k];}ux/=r;uy/=r;for(int k=0;k<9;++k)collision[p*9+k]=(1-OMEGA)*f[p*9+k]+OMEGA*eq(r,WEIGHT[k],DX[k],DY[k],ux,uy);}}for(int y=0;y<H;++y)for(int x=0;x<W;++x)for(int k=0;k<9;++k){int sx=x-DX[k],sy=y-DY[k];if(sx>0&&sx<W-1&&sy>0&&sy<H-1)out[(x+W*y)*9+k]=collision[(sx+W*sy)*9+k];}std::swap(f,out);}auto ret=encode(f),scratch=encode(out);ret.insert(ret.end(),scratch.begin(),scratch.end());return ret;}
int main(){std::vector<Case>cases;std::vector<double>prefix;for(bool perturbed:{false,true}){Case c;c.a.resize(N);c.b.resize(N*4);c.c.resize(N*4);c.types.resize(N);for(int y=0;y<H;++y)for(int x=0;x<W;++x){int p=x+W*y;double r=perturbed?1+((17*x+13*y)%9)/64.:1.,ux=perturbed?1./128:0.,uy=perturbed?-1./256:0.;c.types[p]=x==0||x==W-1||y==0||y==H-1||(perturbed&&x>=120&&x<=123&&y>=12&&y<=19);c.a[p]=eq(r,WEIGHT[0],0,0,ux,uy);for(int k=0;k<4;++k){c.b[p*4+k]=eq(r,WEIGHT[k+1],DX[k+1],DY[k+1],ux,uy);c.c[p*4+k]=eq(r,WEIGHT[k+5],DX[k+5],DY[k+5],ux,uy);}}prefix.insert(prefix.end(),c.a.begin(),c.a.end());prefix.insert(prefix.end(),c.b.begin(),c.b.end());prefix.insert(prefix.end(),c.c.begin(),c.c.end());for(auto t:c.types)prefix.push_back(t);prefix.push_back(OMEGA);prefix.insert(prefix.end(),WEIGHT,WEIGHT+9);prefix.push_back(W);prefix.push_back(H);c.want=oracle(c);ck(cudaMalloc(&c.da,N*8));ck(cudaMalloc(&c.oa,N*8));ck(cudaMalloc(&c.db,N*32));ck(cudaMalloc(&c.ob,N*32));ck(cudaMalloc(&c.dc,N*32));ck(cudaMalloc(&c.oc,N*32));ck(cudaMalloc(&c.dt,N));ck(cudaMemcpy(c.dt,c.types.data(),N,cudaMemcpyHostToDevice));cases.push_back(c);}double*dw;ck(cudaMalloc(&dw,72));ck(cudaMemcpy(dw,WEIGHT,72,cudaMemcpyHostToDevice));double8 dx{1,0,-1,0,1,-1,-1,1},dy{0,1,0,-1,1,1,-1,-1};auto run=[&](Case&c,std::vector<double>&got){ck(cudaMemcpy(c.da,c.a.data(),N*8,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.oa,c.a.data(),N*8,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.db,c.b.data(),N*32,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.ob,c.b.data(),N*32,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.dc,c.c.data(),N*32,cudaMemcpyHostToDevice));ck(cudaMemcpy(c.oc,c.c.data(),N*32,cudaMemcpyHostToDevice));auto a=c.da,oa=c.oa;auto b=c.db,ob=c.ob,cc=c.dc,oc=c.oc;ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int t=0;t<8;++t){lbm<<<dim3(256,1),dim3(1,H)>>>(a,oa,b,ob,cc,oc,c.dt,dx,dy,dw,OMEGA);std::swap(a,oa);std::swap(b,ob);std::swap(cc,oc);}ck(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/8;got.resize(N*18);ck(cudaMemcpy(got.data(),a,N*8,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+N,b,N*32,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+N*5,cc,N*32,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+N*9,oa,N*8,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+N*10,ob,N*32,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+N*14,oc,N*32,cudaMemcpyDeviceToHost));return elapsed;};for(auto&c:cases){std::vector<double>unused;run(c,unused);}for(int tr=1;tr<=5;++tr){std::vector<double>out=prefix;double elapsed=0,err=0;for(auto&c:cases){std::vector<double>got;elapsed+=run(c,got);for(size_t i=0;i<got.size();++i)err=std::max(err,std::abs(got[i]-c.want[i]));out.insert(out.end(),got.begin(),got.end());}bool ok=err<=1e-10;for(double v:out)ok&=std::isfinite(v);std::string path="trial_"+std::to_string(tr)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(out.data(),8,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":458776,\"max_abs_error\":%.17g,\"timing_region\":\"sum_two_fixtures_eightstep_lbm_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":8,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":458776,\"byte_order\":\"little\"}}\n",tr,elapsed,ok?"true":"false",err,path.c_str());if(!ok)return 3;}for(auto&c:cases){cudaFree(c.da);cudaFree(c.oa);cudaFree(c.db);cudaFree(c.ob);cudaFree(c.dc);cudaFree(c.oc);cudaFree(c.dt);}cudaFree(dw);return 0;}
